17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Shared SHA-256 hex helpers used to derive the owner identity key, household id and customer-code
25	 * hash. Centralises the digest-and-hex boilerplate so those derivations differ only in hex case and
26	 * truncation length rather than each carrying their own copy.
27	 */
28	public final class HashUtils {
29	
30	    private HashUtils() {
31	    }
32	
33	    /**
34	     * Returns the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code seed} (64 hex
35	     * characters).
36	     */
37	    public static String sha256Hex(String seed) {
38	        try {
39	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
40	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
41	            StringBuilder sb = new StringBuilder(hash.length * 2);
42	            for (byte b : hash) {
43	                sb.append(String.format("%02x", b));
44	            }
45	            return sb.toString();
46	        }
47	        catch (NoSuchAlgorithmException e) {
48	            throw new IllegalStateException("SHA-256 not available", e);
49	        }
50	    }
51	
52	    /**
53	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
54	     * bytes of {@code seed}.
55	     */
56	    public static String sha256UpperHex(String seed, int length) {
57	        return sha256Hex(seed).substring(0, length).toUpperCase();
58	    }
59	}
