17	package org.springframework.samples.petclinic.audit;
18	
19	import java.util.concurrent.atomic.AtomicLong;
20	
21	import org.slf4j.Logger;
22	import org.slf4j.LoggerFactory;
23	import org.springframework.stereotype.Component;
24	
25	import tools.jackson.databind.ObjectMapper;
26	
27	/**
28	 * Emits immutable structured audit events to the dedicated {@code AUDIT} logger. The sequence
29	 * counter, the event shape and its JSON serialization are a single cohesive concern kept here,
30	 * off the REST controller and on the standard Jackson path this codebase already uses.
31	 */
32	@Component
33	public class OwnerAuditEvents {
34	
35	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
36	
37	    /** Monotonically increasing sequence stamped onto every OWNER_CREATED event, across all creates. */
38	    private final AtomicLong seq = new AtomicLong();
39	
40	    private final ObjectMapper objectMapper;
41	
42	    public OwnerAuditEvents(ObjectMapper objectMapper) {
43	        this.objectMapper = objectMapper;
44	    }
45	
46	    /**
47	     * Emit the immutable {@code OWNER_CREATED} event, stamping a fresh monotonically increasing
48	     * {@code seq}. The {@code customerCode} argument is the owner's <em>current</em> primary
49	     * identifier (see {@code Owner#primaryIdentifier}); when that identifier is later unified into
50	     * the memberId, the event carries the memberId without any change here.
51	     */
52	    public void ownerCreated(Integer ownerId, String customerCode, Integer membershipLevel) {
53	        OwnerCreatedEvent event = new OwnerCreatedEvent(
54	            seq.incrementAndGet(), ownerId, customerCode, membershipLevel, "OWNER_CREATED");
55	        auditLogger.info(objectMapper.writeValueAsString(event));
56	    }
57	
58	    /** Immutable structured OWNER_CREATED audit event. */
59	    record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
60	                             Integer membershipLevel, String event) {
61	    }
62	}
