256	    /** Fixed city-to-region table used to derive an owner's region for its customer code. */
257	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
258	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
259	
260	    /** Region to inclusive 4-digit postcode range {low, high}, preferred over the city table
261	     *  when deriving an owner's region. */
262	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
263	        "NSW", new int[] {2000, 2099},
264	        "VIC", new int[] {3000, 3099},
265	        "QLD", new int[] {4000, 4099});
266	
267	    /**
268	     * Builds an owner's customer code formatted {@code '<REGION>-<HASH8>'}, where REGION is the
269	     * region code derived from the owner's postcode (see {@link #deriveRegion(Owner)}) and HASH8 is
270	     * the first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized
271	     * telephone concatenated with its last name (e.g. {@code 'NSW-1A2B3C4D'}). The old per-city
272	     * sequence numbers have been dropped: the identity is now purely region-and-hash.
273	     *
274	     * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code '-<n>'}
275	     * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
276	     * always receive distinct customer codes.
277	     */
278	    private String generateCustomerCode(Owner owner) {
279	        String base = String.format("%s-%s", deriveRegion(owner), hash8(owner));
280	        Set<String> existing = ownerRepository.findAll().stream()
281	            .map(Owner::getCustomerCode)
282	            .filter(Objects::nonNull)
283	            .collect(Collectors.toSet());
284	        if (!existing.contains(base)) {
285	            return base;
286	        }
287	        for (int n = 2; ; n++) {
288	            String candidate = base + "-" + n;
289	            if (!existing.contains(candidate)) {
290	                return candidate;
291	            }
292	        }
293	    }
294	
295	    /**
296	     * Derives an owner's region code, preferring the postcode: the region whose inclusive 4-digit
297	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used first. When
298	     * the postcode is absent or in no known range, it falls back to the fixed city-to-region table
299	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the
300	     * city is not in the table.
301	     */
302	    private static String deriveRegion(Owner owner) {
303	        String postcode = owner.getPostcode();
304	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
305	            int value = Integer.parseInt(postcode);
306	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
307	                int[] range = entry.getValue();
308	                if (value >= range[0] && value <= range[1]) {
309	                    return entry.getKey();
310	                }
311	            }
312	        }
313	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
314	    }
315	
316	    /**
317	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
318	     * digest over its normalized telephone concatenated with its last name.
319	     */
320	    private static String hash8(Owner owner) {
321	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
322	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
323	        return HashUtils.sha256UpperHex(telephone + lastName, 8);
324	    }
