418	    /**
419	     * Computes an owner's deterministic household id: the first 12 upper-case hex characters of the
420	     * SHA-256 digest over the owner's normalized last name, a {@code '|'} separator and its postcode
421	     * ({@code normalizedLastName + '|' + postcode}). Owners that share a last name and postcode
422	     * therefore map to the same household id automatically, without any explicit linking. Returns
423	     * {@code null} when the last name or postcode is absent or blank, since no household can be
424	     * formed without both.
425	     */
426	    @Override
427	    @Transactional(readOnly = true)
428	    public String computeHouseholdId(Owner owner) throws DataAccessException {
429	        if (owner == null) {
430	            return null;
431	        }
432	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
433	        String postcode = owner.getPostcode();
434	        if (normalizedLastName == null || normalizedLastName.isBlank()
435	            || postcode == null || postcode.isBlank()) {
436	            return null;
437	        }
438	        return HashUtils.sha256UpperHex(normalizedLastName + "|" + postcode, 12);
439	    }
440	
441	    /**
442	     * Counts the owners that belong to the household identified by the given (deterministic)
443	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
444	     * the membership-points calculation. Returns {@code 0} when the id is absent.
445	     */
446	    @Override
447	    @Transactional(readOnly = true)
448	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
449	        if (householdId == null || householdId.isBlank()) {
450	            return 0;
451	        }
452	        return (int) ownerRepository.findAll().stream()
453	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
454	            .count();
455	    }
456	
457	    /**
458	     * Returns the existing, non-deleted owners that belong to the household identified by the given
459	     * (deterministic) household id, i.e. the current members of that household. Used to derive the
460	     * membership-level ceiling a new owner joining the household is subject to. Returns an empty
461	     * collection when the id is absent.
462	     */
463	    @Override
464	    @Transactional(readOnly = true)
465	    public Collection<Owner> findOwnersByHouseholdId(String householdId) throws DataAccessException {
466	        if (householdId == null || householdId.isBlank()) {
467	            return List.of();
468	        }
469	        return ownerRepository.findAll().stream()
470	            .filter(existing -> !existing.isDeleted())
471	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
472	            .toList();
473	    }
474	
475	    /**
476	     * Computes the membership-level ceiling for a new owner joining the household identified by the
477	     * given (deterministic) household id: one above the current maximum membershipLevel among the
478	     * existing (non-deleted) household members. The members' live household size is passed explicitly
479	     * to {@link Owner#membershipLevel(Integer)}, so no persistent state is mutated. Returns
480	     * {@code null} when the household has no existing member, so no cap applies to the new owner.
481	     */
482	    @Override
483	    @Transactional(readOnly = true)
484	    public Integer computeMembershipLevelCap(String householdId) throws DataAccessException {
485	        Collection<Owner> members = findOwnersByHouseholdId(householdId);
486	        if (members.isEmpty()) {
487	            return null;
488	        }
489	        int maxLevel = 0;
490	        for (Owner member : members) {
491	            int level = member.membershipLevel(members.size());
492	            if (level > maxLevel) {
493	                maxLevel = level;
494	            }
495	        }
496	        return maxLevel + 1;
497	    }
498	
499	    /**
500	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
501	     * runs of whitespace to a single space and lower-casing, so values that differ only in
502	     * whitespace or letter case are treated as equal.
503	     */
504	    private static String normalizeHouseholdField(String value) {
505	        if (value == null) {
506	            return null;
507	        }
508	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
509	    }
