529	    /**
530	     * Records that the given idempotency key produced the owner with the given id, so a later create
531	     * repeating the key replays that owner instead of duplicating it. No-op when the key is absent.
532	     */
533	    @Override
534	    public void registerIdempotencyKey(String idempotencyKey, Integer ownerId) throws DataAccessException {
