184	    /**
185	     * Computes the Luhn check digit (0-9) over the digits contained in the owner's
186	     * {@code customerCode} for the read-only {@code checkDigit} field. Null when the
187	     * customer code is absent.
188	     */
189	    @Named("formatCheckDigit")
190	    default Integer formatCheckDigit(Owner owner) {
191	        if (owner == null || owner.getCustomerCode() == null) {
192	            return null;
193	        }
194	        String code = owner.getCustomerCode();
195	        int sum = 0;
196	        boolean dbl = true;
197	        for (int i = code.length() - 1; i >= 0; i--) {
198	            char c = code.charAt(i);
199	            if (c < '0' || c > '9') {
200	                continue;
201	            }
202	            int d = c - '0';
203	            if (dbl) {
204	                d *= 2;
205	                if (d > 9) {
206	                    d -= 9;
207	                }
208	            }
209	            sum += d;
210	            dbl = !dbl;
211	        }
212	        return (10 - (sum % 10)) % 10;
213	    }
