144	        // Idempotent replay: a repeat with an already-seen key returns the originally created
145	        // owner with 200 rather than creating (and possibly rejecting as) a duplicate.
146	        Integer existingId = this.clinicService.findOwnerIdByIdempotencyKey(idempotencyKey);
147	        if (existingId != null) {
148	            Owner existing = this.clinicService.findOwnerById(existingId);
149	            if (existing != null) {
150	                return new ResponseEntity<>(toOwnerDtoWithDerived(existing), HttpStatus.OK);
151	            }
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        LocalDate registrationDate = owner.resolveRegistrationDate();
156	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
157	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
158	        }
159	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
160	            return new ResponseEntity<>(HttpStatus.CONFLICT);
161	        }
162	        // The household id is deterministic: owners that share a (normalized lastName, postcode)
163	        // share it automatically. It feeds the membership-level cap and household sizing below.
164	        owner.setHouseholdId(this.clinicService.computeHouseholdId(owner));
165	        // A new owner joining an existing household (owners sharing a normalized lastName and
166	        // postcode) has its membershipLevel capped at one above the current maximum membershipLevel
167	        // among the existing household members. With no existing household member, no cap applies.
168	        owner.setMembershipLevelCap(this.clinicService.computeMembershipLevelCap(owner.getHouseholdId()));
169	        // Hard duplicate detection is consolidated into the owner's derived identity key (see
170	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
171	        // There is no separate household-duplicate 409: two owners sharing a lastName and postcode
172	        // but differing in telephone (or email) have distinct identity keys and are allowed.
173	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
174	            return new ResponseEntity<>(HttpStatus.CONFLICT);
175	        }
176	        // Soft-match: the identity key differs, yet the surname's soundex and the postcode match an
177	        // existing owner, flagged 'possibleDuplicate'. This is exactly the same lastName/postcode,
178	        // different telephone case that is no longer a hard duplicate.
179	        Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
180	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
181	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
182	        owner.setNamesakeCount(
183	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
184	        this.clinicService.saveOwner(owner);
185	        this.clinicService.registerIdempotencyKey(idempotencyKey, owner.getId());
186	        OwnerDto ownerDto = toOwnerDtoWithDerived(owner);
187	        auditLogger.info(
188	            "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
189	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
190	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
191	        // Immutable structured event, in addition to the human-readable line above. It carries the
192	        // owner's CURRENT primary identifier (Owner#primaryIdentifier) so that when the customerCode
193	        // is later unified into the memberId, the event follows without touching this call site.
194	        this.ownerAuditEvents.ownerCreated(
195	            owner.getId(), owner.primaryIdentifier(), ownerDto.getMembershipLevel());
196	        headers.setLocation(UriComponentsBuilder.newInstance()
197	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
