246	    @Override
247	    @Transactional
248	    public void saveOwner(Owner owner) throws DataAccessException {
249	        if (owner.getCustomerCode() == null) {
250	            owner.setCustomerCode(generateCustomerCode(owner));
251	        }
252	        ownerRepository.save(owner);
253	
254	    }
255	
256	    /** Fixed city-to-region table used to derive an owner's region for its customer code. */
257	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
258	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
259	
260	    /** Region to inclusive 4-digit postcode range {low, high}, preferred over the city table
261	     *  when deriving an owner's region. */
262	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
263	        "NSW", new int[] {2000, 2099},
264	        "VIC", new int[] {3000, 3099},
265	        "QLD", new int[] {4000, 4099});
266	
267	    /**
268	     * Builds an owner's customer code formatted {@code '<REGION>-<HASH8>'}, where REGION is the
269	     * region code derived from the owner's postcode (see {@link #deriveRegion(Owner)}) and HASH8 is
270	     * the first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized
271	     * telephone concatenated with its last name (e.g. {@code 'NSW-1A2B3C4D'}). The old per-city
272	     * sequence numbers have been dropped: the identity is now purely region-and-hash.
273	     *
274	     * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code '-<n>'}
275	     * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
276	     * always receive distinct customer codes.
277	     */
278	    private String generateCustomerCode(Owner owner) {
279	        String base = String.format("%s-%s", deriveRegion(owner), hash8(owner));
280	        Set<String> existing = ownerRepository.findAll().stream()
281	            .map(Owner::getCustomerCode)
282	            .filter(Objects::nonNull)
283	            .collect(Collectors.toSet());
284	        if (!existing.contains(base)) {
285	            return base;
286	        }
287	        for (int n = 2; ; n++) {
288	            String candidate = base + "-" + n;
289	            if (!existing.contains(candidate)) {
290	                return candidate;
291	            }
292	        }
293	    }
294	
295	    /**
296	     * Derives an owner's region code, preferring the postcode: the region whose inclusive 4-digit
297	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used first. When
298	     * the postcode is absent or in no known range, it falls back to the fixed city-to-region table
299	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the
300	     * city is not in the table.
301	     */
302	    private static String deriveRegion(Owner owner) {
303	        String postcode = owner.getPostcode();
304	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
305	            int value = Integer.parseInt(postcode);
306	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
307	                int[] range = entry.getValue();
308	                if (value >= range[0] && value <= range[1]) {
309	                    return entry.getKey();
310	                }
311	            }
312	        }
313	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
314	    }
315	
316	    /**
317	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
318	     * digest over its normalized telephone concatenated with its last name.
319	     */
320	    private static String hash8(Owner owner) {
321	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
322	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
323	        return HashUtils.sha256UpperHex(telephone + lastName, 8);
324	    }
325	
326	    /**
327	     * Whether any existing owner has the given derived identity key. This is the single basis for
328	     * duplicate detection: a create is rejected only when the whole key matches an existing owner
329	     * exactly. See {@link Owner#getIdentityKey()} for the key's definition.
330	     */
331	    @Override
332	    @Transactional(readOnly = true)
333	    public boolean existsOwnerWithIdentityKey(String identityKey) throws DataAccessException {
334	        if (identityKey == null) {
335	            return false;
336	        }
337	        return ownerRepository.findAll().stream()
338	            .filter(existing -> !existing.isDeleted())
339	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
340	    }
341	
342	    /**
343	     * Finds the id of an existing owner that {@code owner} soft-matches (a possible duplicate): one
344	     * whose surname shares this owner's {@code soundex(lastName)} and whose postcode matches, yet
345	     * whose identity key differs (so it is not itself a hard duplicate). This is a weaker match than
346	     * the hard-duplicate identity key, so it is only meaningful for an owner that is not itself a hard
347	     * duplicate; in particular two owners with the same lastName and postcode but different telephones
348	     * are soft matches rather than hard duplicates. When several owners match, the one with the lowest
349	     * id is returned; {@code null} is returned when there is no match (or lastName/postcode is absent),
350	     * meaning the owner is not a possible duplicate.
351	     */
352	    @Override
353	    @Transactional(readOnly = true)
354	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
355	        if (owner == null || owner.getLastName() == null || owner.getPostcode() == null) {
356	            return null;
357	        }
358	        String soundex = Owner.soundex(owner.getLastName());
359	        String postcode = owner.getPostcode();
360	        String identityKey = owner.getIdentityKey();
361	        return ownerRepository.findAll().stream()
362	            .filter(existing -> !existing.isDeleted())
363	            .filter(existing -> soundex.equals(Owner.soundex(existing.getLastName()))
364	                && postcode.equals(existing.getPostcode())
365	                && !Objects.equals(identityKey, existing.getIdentityKey()))
366	            .map(Owner::getId)
367	            .filter(Objects::nonNull)
368	            .min(Comparator.naturalOrder())
369	            .orElse(null);
370	    }
371	
372	    /**
373	     * Counts the existing owners whose firstName and lastName match the given values
374	     * case-insensitively. Used to record an owner's namesake count at creation time.
375	     */
376	    @Override
377	    @Transactional(readOnly = true)
378	    public int countOwnersByName(String firstName, String lastName) throws DataAccessException {
379	        if (firstName == null || lastName == null) {
380	            return 0;
381	        }
382	        return (int) ownerRepository.findAll().stream()
383	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
384	                && lastName.equalsIgnoreCase(existing.getLastName()))
385	            .count();
386	    }
387	
388	    /**
389	     * Counts the existing owners whose city matches the given value case-insensitively.
390	     * Used to enforce the per-city capacity rule at creation time.
391	     */
392	    @Override
393	    @Transactional(readOnly = true)
394	    public int countOwnersByCity(String city) throws DataAccessException {
395	        if (city == null) {
396	            return 0;
397	        }
398	        return (int) ownerRepository.findAll().stream()
399	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
400	            .count();
401	    }
402	
403	    /**
404	     * Counts the existing owners whose registration date matches the given value.
405	     * Used to enforce the per-day owner creation limit.
406	     */
407	    @Override
408	    @Transactional(readOnly = true)
409	    public int countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
410	        if (registrationDate == null) {
411	            return 0;
412	        }
413	        return (int) ownerRepository.findAll().stream()
414	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
415	            .count();
416	    }
417	
418	    /**
419	     * Computes an owner's deterministic household id: the first 12 upper-case hex characters of the
420	     * SHA-256 digest over the owner's normalized last name, a {@code '|'} separator and its postcode
421	     * ({@code normalizedLastName + '|' + postcode}). Owners that share a last name and postcode
422	     * therefore map to the same household id automatically, without any explicit linking. Returns
423	     * {@code null} when the last name or postcode is absent or blank, since no household can be
424	     * formed without both.
425	     */
426	    @Override
427	    @Transactional(readOnly = true)
428	    public String computeHouseholdId(Owner owner) throws DataAccessException {
429	        if (owner == null) {
430	            return null;
431	        }
432	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
433	        String postcode = owner.getPostcode();
434	        if (normalizedLastName == null || normalizedLastName.isBlank()
435	            || postcode == null || postcode.isBlank()) {
436	            return null;
437	        }
438	        return HashUtils.sha256UpperHex(normalizedLastName + "|" + postcode, 12);
439	    }
440	
441	    /**
442	     * Counts the owners that belong to the household identified by the given (deterministic)
443	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
444	     * the membership-points calculation. Returns {@code 0} when the id is absent.
445	     */
446	    @Override
447	    @Transactional(readOnly = true)
448	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
449	        if (householdId == null || householdId.isBlank()) {
450	            return 0;
451	        }
452	        return (int) ownerRepository.findAll().stream()
453	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
454	            .count();
455	    }
456	
457	    /**
458	     * Returns the existing, non-deleted owners that belong to the household identified by the given
459	     * (deterministic) household id, i.e. the current members of that household. Used to derive the
460	     * membership-level ceiling a new owner joining the household is subject to. Returns an empty
461	     * collection when the id is absent.
462	     */
463	    @Override
464	    @Transactional(readOnly = true)
465	    public Collection<Owner> findOwnersByHouseholdId(String householdId) throws DataAccessException {
466	        if (householdId == null || householdId.isBlank()) {
467	            return List.of();
468	        }
469	        return ownerRepository.findAll().stream()
470	            .filter(existing -> !existing.isDeleted())
471	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
472	            .toList();
473	    }
474	
475	    /**
476	     * Computes the membership-level ceiling for a new owner joining the household identified by the
477	     * given (deterministic) household id: one above the current maximum membershipLevel among the
478	     * existing (non-deleted) household members. The members' live household size is passed explicitly
479	     * to {@link Owner#membershipLevel(Integer)}, so no persistent state is mutated. Returns
480	     * {@code null} when the household has no existing member, so no cap applies to the new owner.
481	     */
482	    @Override
483	    @Transactional(readOnly = true)
484	    public Integer computeMembershipLevelCap(String householdId) throws DataAccessException {
485	        Collection<Owner> members = findOwnersByHouseholdId(householdId);
486	        if (members.isEmpty()) {
487	            return null;
488	        }
489	        int maxLevel = 0;
490	        for (Owner member : members) {
491	            int level = member.membershipLevel(members.size());
492	            if (level > maxLevel) {
493	                maxLevel = level;
494	            }
495	        }
496	        return maxLevel + 1;
497	    }
498	
499	    /**
500	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
501	     * runs of whitespace to a single space and lower-casing, so values that differ only in
502	     * whitespace or letter case are treated as equal.
503	     */
504	    private static String normalizeHouseholdField(String value) {
505	        if (value == null) {
506	            return null;
507	        }
508	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
509	    }
510	
511	    @Override
512	    @Transactional(readOnly = true)
513	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
514	        return ownerRepository.findByLastName(lastName);
515	    }
516	
517	    /**
518	     * Returns the id of the owner previously created for the given idempotency key, or {@code null}
519	     * when the key has not been seen (or is absent), meaning the create should proceed normally.
520	     */
521	    @Override
522	    public Integer findOwnerIdByIdempotencyKey(String idempotencyKey) throws DataAccessException {
523	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
524	            return null;
525	        }
526	        return idempotencyKeys.get(idempotencyKey);
527	    }
528	
529	    /**
530	     * Records that the given idempotency key produced the owner with the given id, so a later create
531	     * repeating the key replays that owner instead of duplicating it. No-op when the key is absent.
532	     */
533	    @Override
534	    public void registerIdempotencyKey(String idempotencyKey, Integer ownerId) throws DataAccessException {
535	        if (idempotencyKey == null || idempotencyKey.isBlank() || ownerId == null) {
536	            return;
537	        }
538	        idempotencyKeys.put(idempotencyKey, ownerId);
539	    }
540	
541	    @Override
542	    @Transactional(readOnly = true)
543	    public Collection<Visit> findVisitsByPetId(int petId) {
544	        return visitRepository.findByPetId(petId);
545	    }
546	
547	    @Override
548	    @Transactional(readOnly = true)
549	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
550	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
551	    }
552	
553	    private <T> T findEntityById(Supplier<T> supplier) {
554	        try {
555	            return supplier.get();
556	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
557	            // Just ignore not found exceptions for Jdbc/Jpa realization
558	            return null;
559	        }
560	    }
561	
562	}
